    fn feedback_category_options_exist() {
        let category_prompt = Prompt {
            key: "feedback_category".to_string(),
            question: "What kind of feedback?".to_string(),
            prompt_type: PromptType::Select {
                options: vec![
                    PromptOption {
                        label: "Bug - something broke".to_string(),
                        value: "bug".to_string(),
