                let blocking: Vec<_> = gaps
                    .iter()
                    .filter(|g| !g.status.is_satisfied() && !g.status.can_proceed())
                    .collect();
                if !blocking.is_empty() {
                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();

