    // --- 6D: SystemOnly tests ---

    #[test]
    fn system_only_warns_and_proceeds() {
        let registry = RequirementRegistry::new();
        let probe = make_probe();
        let temp = TempDir::new().unwrap();
        let mut checker = make_checker(&registry, &probe, &temp);
